/* khipuFibra · catálogo con datos públicos y panel conectado a Supabase cuando está configurado. */
(()=>{'use strict';
const KEY='khipuFibra_v2';
const initial={logged:false,artisan:{name:'María del Carmen Vega',city:'Ciudad Eten, Lambayeque',specialty:'Tejidos a crochet y accesorios de algodón',bio:'Aprendí a tejer junto a mi madre y hoy confecciono bolsos y textiles que combinan técnicas tradicionales con diseños contemporáneos. Elaboro cada pieza a mano y atiendo pedidos personalizados.',story:'Empecé con pequeños encargos de mi comunidad. Ahora deseo mostrar mis creaciones en todo el Perú y compartir lo que he aprendido con otras mujeres artesanas.',avatar:'',experience:'12 años creando',facebook:'https://www.facebook.com/',instagram:'https://www.instagram.com/',youtube:'https://www.youtube.com/',tiktok:'https://www.tiktok.com/',video:'',fair:'Feria de artesanía local y encuentros de emprendimiento regional',whatsapp:'933860919'},products:[],favorites:[],ratings:[],draft:{name:'',category:'Bolsos',material:'',price:'',stock:'Disponible',dimensions:'',story:'',care:'',photos:[],ai:{text:'',image:'',social:'',textOK:false,imageOK:false,socialOK:false,tv:0,iv:0,sv:0}},posted:[]};
const demoArtisans=[{name:'María del Carmen Vega',city:'Ciudad Eten, Lambayeque',specialty:'Tejidos y accesorios de algodón',bio:'Tejedora de tercera generación. Combino puntos tradicionales y colores modernos para crear bolsos, manteles y detalles para regalo. Realizo pedidos personalizados.',story:'Cada pieza lleva tiempo, cariño y la historia de las manos que me enseñaron a tejer.',experience:'12 años de experiencia',fair:'Ferias de emprendimiento en Lambayeque',avatar:'🧶',facebook:'https://www.facebook.com/',instagram:'https://www.instagram.com/',youtube:'https://www.youtube.com/',tiktok:'https://www.tiktok.com/',video:''},{name:'Rosa Huamán',city:'Monsefú, Lambayeque',specialty:'Cestería y accesorios de fibra vegetal',bio:'Trabajo con fibras vegetales para confeccionar canastas, carteras y sombreros. Mi taller familiar apuesta por objetos útiles con una estética natural y acabados cuidadosos.',story:'Quiero que las nuevas generaciones conozcan el valor del trabajo artesanal.',experience:'9 años de experiencia',fair:'Exposiciones y ferias artesanales de Monsefú',avatar:'🪡',facebook:'https://www.facebook.com/',instagram:'https://www.instagram.com/',youtube:'https://www.youtube.com/',tiktok:'https://www.tiktok.com/',video:''},{name:'Elena Pérez',city:'Mórrope, Lambayeque',specialty:'Cerámica y decoración artesanal',bio:'Elaboro piezas de cerámica decorativa inspiradas en formas y colores del entorno. Me gusta crear objetos para hogares y obsequios con una historia propia.',story:'La artesanía transforma materiales cotidianos en recuerdos especiales.',experience:'7 años de experiencia',fair:'Ferias culturales y encuentros de artistas locales',avatar:'🏺',facebook:'https://www.facebook.com/',instagram:'https://www.instagram.com/',youtube:'https://www.youtube.com/',tiktok:'https://www.tiktok.com/',video:''}];
const demoReviews={product:{d1:[['Lucía R.',5,'Los detalles del tejido son preciosos y el tamaño es muy práctico.'],['Ana P.',5,'Me encantó la combinación de colores.']],d2:[['Carlos M.',5,'Excelente para organizar la sala.']],d3:[['Paola G.',4,'Muy bonito, queda bien en la mesa.']],d4:[['Teresa L.',5,'Cómodo y con un tejido muy cuidado.']],d5:[['Milagros S.',5,'Elegante y resistente.']],d6:[['Jorge T.',4,'Un detalle diferente para regalar.']]},artisan:{'María del Carmen Vega':[['Patricia R.',5,'Muy amable y atenta con las consultas.'],['Diana M.',5,'Me explicó los cuidados y cumplió con lo acordado.']], 'Rosa Huamán':[['Elisa P.',5,'Trabajo bien terminado y bonita presentación.']], 'Elena Pérez':[['Renato S.',4,'Buena comunicación y piezas originales.']]}};
const artist=n=>n===state.artisan.name && state.logged?{...demoArtisans[0],...state.artisan}:cloudProfiles.find(a=>a.name===n)||demoArtisans.find(a=>a.name===n)||demoArtisans[0];
const profiles=()=>[...cloudProfiles,...demoArtisans.filter(a=>!cloudProfiles.some(c=>c.name===a.name))];
const reviews=(kind,id)=>[...(demoReviews[kind]?.[id]||[]).map((r,i)=>({id:'sample'+i,name:r[0],score:r[1],comment:r[2],date:'2026-10-18'})),...(cloud.enabled?cloudReviews:state.ratings||[]).filter(r=>r.kind===kind&&String(r.target)===String(id))];
const rating=(kind,id)=>{const rr=reviews(kind,id);return rr.length?`<span class="rating-stars">★ ${ (rr.reduce((a,r)=>a+r.score,0)/rr.length).toFixed(1)}</span> <span class="muted small">(${rr.length} opiniones)</span>`:'<span class="muted small">Sin calificaciones aún</span>'};
const ratingPanel=(kind,id)=>`<section class="section reviews-section"><div class="section-head"><div><span class="eyebrow">Opiniones de la comunidad</span><h2>Calificaciones y comentarios</h2><div>${rating(kind,id)}</div></div></div><div class="grid2"><div class="review-list">${reviews(kind,id).slice().reverse().map(r=>`<div class="review"><div class="topline"><b>${esc(r.name)}${String(r.id||'').startsWith('sample')?'<span class="example-rating">Opinión de ejemplo</span>':''}</b><span class="rating-stars">${'★'.repeat(r.score)}${'☆'.repeat(5-r.score)}</span></div><p>${esc(r.comment)}</p><small class="muted">${esc(r.date)}</small></div>`).join('')}</div><form class="panel rating-form" data-kind="${attr(kind)}" data-target="${attr(id)}"><h3>Comparte tu experiencia</h3><p class="muted small">Tu opinión ayuda a otras personas a elegir.</p><div class="field"><label for="reviewName">Tu nombre</label><input class="input" id="reviewName" name="name" required minlength="2" maxlength="50" placeholder="Ej. Carmen R."></div><div class="field"><label for="reviewScore">Tu calificación</label><select class="select" id="reviewScore" name="score" required><option value="5">★★★★★ Excelente (5)</option><option value="4">★★★★☆ Muy bueno (4)</option><option value="3">★★★☆☆ Bueno (3)</option><option value="2">★★☆☆☆ Regular (2)</option><option value="1">★☆☆☆☆ Malo (1)</option></select></div><div class="field"><label for="reviewComment">¿Cómo fue tu experiencia?</label><textarea class="textarea" id="reviewComment" name="comment" minlength="10" maxlength="400" required placeholder="Cuéntanos qué te pareció..."></textarea></div><button class="btn" type="submit">Publicar mi valoración</button><p class="muted small" style="margin-top:12px">${cloud.enabled?'Tu valoración se enviará a revisión antes de aparecer públicamente.':'La opinión se guarda en este navegador.'}</p></form></div></section>`;

const demoProducts=[
{id:'d1',name:'Bolso Amanecer de Algodón',category:'Bolsos',material:'Algodón tejido a crochet',price:85,img:'assets/bolso.svg',story:'Un bolso de uso diario inspirado en los tonos cálidos del amanecer. Tejido punto por punto con una combinación de textura y ligereza.',dimensions:'32 × 27 cm; asa de 55 cm',care:'Lavar a mano con agua fría; secar a la sombra.',stock:'Disponible; personalizable por encargo',time:'4 a 6 días por encargo',artisan:'María del Carmen Vega',collection:'Regalos con identidad'},
{id:'d2',name:'Canasta Nido Natural',category:'Decoración',material:'Fibra vegetal trenzada',price:65,img:'assets/cesto.svg',story:'Canasta versátil para guardar objetos o decorar interiores. Su apariencia natural combina con espacios acogedores.',dimensions:'25 cm de diámetro × 18 cm de alto',care:'Limpiar con un paño seco; evitar humedad continua.',stock:'Disponible',time:'3 a 5 días',artisan:'María del Carmen Vega',collection:'Hogar artesanal'},
{id:'d3',name:'Camino de Mesa Tradición',category:'Textiles',material:'Hilo de algodón',price:110,img:'assets/mantel.svg',story:'Textil de mesa diseñado para reuniones familiares. Cada puntada se realiza cuidadosamente para resaltar la trama del tejido.',dimensions:'120 × 35 cm',care:'Lavar a mano; planchar a baja temperatura con tela protectora.',stock:'Por pedido',time:'6 a 8 días',artisan:'María del Carmen Vega',collection:'Hogar artesanal'},
{id:'d4',name:'Sombrero Brisa Norteña',category:'Accesorios',material:'Fibra vegetal entretejida',price:70,img:'assets/sombrero.svg',story:'Sombrero ligero pensado para paseos y días soleados. Acabado artesanal con textura natural.',dimensions:'Talla ajustable: contorno aproximado 56–58 cm',care:'Guardar sin aplastar; limpiar con cepillo suave.',stock:'Disponible',time:'2 a 4 días',artisan:'Rosa Huamán',collection:'Verano y ferias'},
{id:'d5',name:'Cartera Raíces del Norte',category:'Bolsos',material:'Fibra vegetal y asas tejidas',price:95,img:'assets/cartera.svg',story:'Cartera con fibras de tono natural y acabado artesanal, pensada para combinar con prendas casuales.',dimensions:'28 × 23 × 9 cm',care:'Mantener seca; limpiar suavemente sin detergentes fuertes.',stock:'Por encargo',time:'5 a 7 días',artisan:'Rosa Huamán',collection:'Regalos con identidad'},
{id:'d6',name:'Jarrón Tierra y Memoria',category:'Decoración',material:'Cerámica decorativa',price:58,img:'assets/decoracion.svg',story:'Pieza decorativa elaborada manualmente con un acabado cálido. Ideal para decorar estantes y espacios personales.',dimensions:'18 cm de alto × 11 cm de ancho',care:'Limpiar con paño ligeramente húmedo; evitar golpes.',stock:'Disponible',time:'3 a 5 días',artisan:'Elena Pérez',collection:'Hogar artesanal'}];
let state;try{state=JSON.parse(localStorage.getItem(KEY)||localStorage.getItem('quipufibra_mockup_v1'))||structuredClone(initial)}catch{state=JSON.parse(JSON.stringify(initial))};state={...initial,...state,artisan:{...initial.artisan,...state.artisan},draft:{...initial.draft,...state.draft,ai:{...initial.draft.ai,...(state.draft?.ai||{})}}};state.ratings=state.ratings||[];if(state.artisan.name==='María del Carmen')state.artisan.name='María del Carmen Vega';
let cloudProfiles=[];let cloudReviews=[];const cloud=window.khipuCloud||{enabled:false};
const store=()=>{try{if(cloud.enabled){localStorage.setItem(KEY,JSON.stringify({favorites:state.favorites}));if(cloud.approved&&cloud.user)sessionStorage.setItem('khipuFibra_private_'+cloud.user.id,JSON.stringify({draft:state.draft}));}else localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){toast('No se pudo guardar: el navegador está lleno. Prueba imágenes más pequeñas.');return false}};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=x=>esc(x);const src=x=>/^data:image\/(jpeg|png|webp);base64,/i.test(x||'')||/^(assets\/|https:\/\/)/.test(x||'')?attr(x):'assets/bolso.svg';
const all=()=>[...state.products,...demoProducts];const get=id=>all().find(p=>String(p.id)===String(id));const getId=()=>new URLSearchParams(location.search).get('id');const page=document.body.dataset.page;
const link=(text,url,cl='btn')=>`<a class="${cl}" href="${url}">${text}</a>`;
const social=(name,url,cl='')=>/^https:\/\//i.test(url||'')?`<a class="social ${cl}" href="${attr(url)}" target="_blank" rel="noopener noreferrer">${name} ↗</a>`:'';
const wha=p=>{const a=artist(p.artisan||'');const phone=String(a.whatsapp||'933860919').replace(/\D/g,'');const normalized=phone.length===9?'51'+phone:phone;const url=new URL(p.id?'producto.html?id='+encodeURIComponent(p.id):'artesana.html?nombre='+encodeURIComponent(a.name),location.href).href;return 'https://wa.me/'+normalized+'?text='+encodeURIComponent('Hola, vi «'+p.name+'» en khipuFibra. Quisiera consultar su disponibilidad.\n'+url);};
const toast=m=>{document.querySelector('.toast')?.remove();let t=document.createElement('div');t.className='toast';t.setAttribute('role','status');t.setAttribute('aria-live','polite');t.textContent=m;document.body.appendChild(t);setTimeout(()=>t.remove(),3900)};
const top=()=>{const nav=[['Inicio','index.html'],['Catálogo','catalogo.html'],['Artesanas','artesanas.html'],['Mis favoritos','favoritos.html']];return `<a class="skip-link" href="#mainContent">Saltar al contenido</a><header class="header nav"><div class="container headrow"><a class="brand" href="index.html"><span class="logo-placeholder" id="logoSpace"><img src="assets/logo-header-144.png" srcset="assets/logo-header-104.png 104w, assets/logo-header-144.png 144w" sizes="(max-width: 599px) 52px, 72px" alt="" width="72" height="72" decoding="async"></span><span><span class="brandname">khipuFibra</span><small>Historias que se comparten</small></span></a><button class="mobile-trigger" id="toggleMenu" aria-label="Abrir menú" aria-expanded="false" aria-controls="mainnav">Menú</button><nav class="nav" id="mainnav" aria-label="Navegación principal">${nav.map(([n,u])=>`<a class="${page===(u.replace('.html',''))?'active':''}" ${page===u.replace('.html','')?'aria-current="page"':''} href="${u}">${n}</a>`).join('')}<a class="nav-cta" href="${cloud.membership?.role==='admin'&&cloud.membership?.status==='active'?'admin.html':state.logged?'panel.html':'acceso.html'}">${cloud.membership?.role==='admin'&&cloud.membership?.status==='active'?'Administración':state.logged?'Mi espacio':'Soy socio'} ↗</a></nav></div></header>`};
const foot=()=>`<footer class="footer"><div class="container"><div class="footrow"><div><strong class="footer-brand">khipuFibra</strong><p>Artesanía, identidad y difusión digital.</p><span class="small">Artesanía y emprendimiento · Perú</span></div><nav class="footer-nav" aria-label="Enlaces del pie de página"><a href="catalogo.html">Catálogo</a><a href="artesanas.html">Conocer artesanas</a><a href="favoritos.html">Mis favoritos</a><a href="acceso.html">Espacio artesana</a></nav></div>${page==='index'?'<p class="footer-credit">Fotografía editorial de referencia vía Wikimedia Commons. No representa a las artesanas de khipuFibra. <a href="creditos.html">Créditos y licencia</a></p>':''}</div></footer>`;
const storefrontContext=()=>({escape:esc,source:src,products:all(),profiles:profiles(),favorites:state.favorites,cards,rating,ratingPanel,whatsapp:wha,artisan:artist,demoProduct:p=>demoProducts.some(item=>String(item.id)===String(p.id)),demoArtisan:name=>!cloudProfiles.some(a=>a.name===name)&&demoArtisans.some(a=>a.name===name)});
const title=(ey,head,sub='')=>`<div class="pageintro"><span class="eyebrow">${ey}</span><h1>${head}</h1>${sub?`<p>${sub}</p>`:''}</div>`;
const legacyCard=p=>`<article class="card"><a href="producto.html?id=${encodeURIComponent(p.id)}"><img src="${src(p.img)}" alt="${attr(p.name)}" loading="lazy"/></a><div class="cardbody"><div class="topline"><span class="tag">${esc(p.category)}</span><button class="iconbtn ${state.favorites.includes(p.id)?'selected':''}" data-fav="${attr(p.id)}" aria-label="Guardar en favoritos">${state.favorites.includes(p.id)?'♥':'♡'}</button></div><h3><a href="producto.html?id=${encodeURIComponent(p.id)}">${esc(p.name)}</a></h3><div class="muted small">Por ${esc(p.artisan||state.artisan.name)}</div><div class="rating-inline">${rating('product',p.id)}</div><div class="topline" style="margin-top:12px"><span class="price">S/ ${esc(p.price||'Consultar')}</span><a class="smalllinks" href="producto.html?id=${encodeURIComponent(p.id)}">Ver producto →</a></div></div></article>`;
const card=p=>window.khipuStorefront?window.khipuStorefront.card(p,{escape:esc,source:src,favorites:state.favorites,rating:rating('product',p.id),demo:demoProducts.some(item=>String(item.id)===String(p.id))}):legacyCard(p);
const cards=ps=>ps.length?`<div class="cards">${ps.map(card).join('')}</div>`:`<div class="empty">Todavía no hay productos en esta sección.<br><a class="smalllinks" href="catalogo.html">Volver al catálogo →</a></div>`;
const sides=[['⌂','Mi panel','panel.html'],['＋','Agregar producto','nuevo.html'],['↗','Difundir en redes','difusion.html'],['♙','Mi perfil','mi-perfil.html']];
const dash=(content,head='')=>`<div class="container section-tight"><div class="sidebar-layout"><aside class="side">${sides.map(([ic,n,u])=>`<a class="${page===(u.replace('.html',''))?'active':''}" href="${u}">${ic} ${n}</a>`).join('')}</aside><div>${head}${content}</div></div></div>`;
const secure=()=>{if(!cloud.enabled||!cloud.approved||!cloud.user){location.replace(cloud.membership?.role==='admin'&&cloud.membership?.status==='active'?'admin.html':'acceso.html');return false;}return true;};
const imgLabel=(p,i)=>`<label class="uploadbox"><span>${['📷','📸','🔎'][i]}</span><b>${['Frente','Lateral','Detalle'][i]}</b><small>Elegir foto</small>${p?`<img src="${src(p)}" alt="Foto ${i+1}"/>`:''}<input type="file" accept="image/*" data-photo="${i}" aria-label="Subir foto ${i+1}"/></label>`;
const draftOK=()=>!!state.draft.name.trim()&&!!state.draft.material.trim();
function show(){let body='';if(['panel','nuevo','estudio','revision','difusion','mi-perfil'].includes(page)&&!secure())return;
switch(page){
case 'index':body=window.khipuStorefront.home(storefrontContext());break;
case 'catalogo':body=window.khipuStorefront.catalog(storefrontContext());break;
case 'producto':{const id=getId();const p=id?get(id):all()[0];body=window.khipuStorefront.product(p,storefrontContext());break;}
case 'artesanas':body=`<div class="container">${title('Personas e historias','Conoce a nuestras artesanas','Explora sus talleres, descubre sus productos y acompaña su trabajo en redes sociales.')}<div class="grid3">${profiles().map((a,i)=>{let cnt=all().filter(p=>p.artisan===a.name).length;return `<article class="panel artisan-card"><div class="avatar" style="margin-bottom:14px">${/^https:\/\//.test(a.avatar||'')?`<img src="${attr(a.avatar)}" alt="Foto de artesana" style="width:100%;height:100%;object-fit:cover;border-radius:50%">`:esc(a.avatar||'🧶')}</div><span class="eyebrow">${esc(a.city)}</span><h3>${esc(a.name)}</h3><p class="muted">${esc(a.specialty)}</p><p class="small">${esc(a.bio)}</p><p>${rating('artisan',a.name)}</p><div class="pillrow"><span class="tag">${cnt} productos</span><span class="tag">${esc(a.experience||'Artesana')}</span></div><div class="socials compact-social">${social('f',a.facebook,'facebook')}${social('◎',a.instagram,'instagram')}${social('▶',a.youtube,'youtube')}${social('♫',a.tiktok,'tiktok')}</div><a class="btn alt wide" style="margin-top:16px" href="artesana.html?nombre=${encodeURIComponent(a.name)}">Ver historia, productos y redes →</a></article>`}).join('')}</div></div>`;break;
case 'artesana':{let name=new URLSearchParams(location.search).get('nombre')||state.artisan.name;let own=name===state.artisan.name;let a=artist(name);let related=all().filter(p=>p.artisan===name);body=`<div class="container">${title('Nuestra comunidad','Perfil de artesana','<a class="smalllinks" href="artesanas.html">← Volver a artesanas</a>')}<div class="profilecover"><div class="avatar">${/^https:\/\//.test(a.avatar||'')?`<img src="${attr(a.avatar)}" alt="Foto de artesana" style="width:100%;height:100%;object-fit:cover;border-radius:50%">`:'🧶'}</div><div><span class="eyebrow">Artesanía peruana</span><h2 style="margin-bottom:3px">${esc(a.name)}</h2><div class="muted">📍 ${esc(a.city)}</div><b>${esc(a.specialty)}</b><div class="rating-inline">${rating('artisan',a.name)}</div></div></div><div class="section grid2"><div><h2>Mi historia</h2><p>${esc(a.bio)}</p><p class="quote">${esc(a.story)}</p><div class="surface"><b>Trayectoria</b><p>${esc(a.experience||'Experiencia artesanal')}</p><b>Participación en ferias</b><p>${esc(a.fair||'Ferias y encuentros culturales')}</p></div><a class="btn" href="${wha({name:'tu perfil',artisan:a.name})}" target="_blank" rel="noopener">☏ Contactar por WhatsApp</a></div><div class="panel"><h3>Encuéntrame también en redes</h3><p class="muted small">Explora sus canales de difusión. Los enlaces personales se configuran desde el panel de cada artesana.</p><div class="socials">${social('f Facebook',a.facebook,'facebook')}${social('◎ Instagram',a.instagram,'instagram')}${social('▶ YouTube',a.youtube,'youtube')}${social('♫ TikTok',a.tiktok,'tiktok')}${!a.facebook&&!a.instagram&&!a.youtube&&!a.tiktok?'<span class="muted small">Las redes aparecerán aquí cuando la artesana agregue sus enlaces.</span>':''}</div><div class="divider"></div><h3>Comparte este perfil</h3><button class="btn alt smallbtn" id="copyProfile">Copiar enlace 🔗</button><button class="btn alt smallbtn" id="showQr" style="margin:6px">Ver QR</button><div id="qrPlace"></div></div></div><div class="section"><div class="section-head"><h2>Sus productos</h2><a href="catalogo.html" class="smalllinks">Todo el catálogo →</a></div>${cards(related)}</div><div class="section"><div class="section-head"><div><span class="eyebrow">Difusión y comunidad</span><h2>Así comparte su trabajo</h2></div></div><div class="grid3 social-post-grid">${related.slice(0,3).map((p,i)=>`<article class="social-post"><div class="post-head"><span class="post-icon">${['◎','f','♫'][i%3]}</span><div><b>${esc(a.name)}</b><div class="muted small">${['Instagram','Facebook','TikTok'][i%3]} · ${['Una nueva creación','Desde mi taller','Detrás de cada detalle'][i%3]}</div></div></div><img src="${src(p.img)}" alt="Artesanía compartida en redes" loading="lazy"><div class="post-text"><b>${esc(p.name)}</b><p>${esc(p.story)}</p><div class="pillrow"><span class="tag">#HechoAMano</span><span class="tag">#khipuFibra</span></div><a class="smalllinks" href="producto.html?id=${encodeURIComponent(p.id)}">Ver la artesanía →</a></div></article>`).join('')}</div></div><div class="section"><h2>Videos de su trabajo</h2>${a.video&&youtubeEmbed(a.video)?`<div class="video" style="max-width:700px"><iframe src="${attr(youtubeEmbed(a.video))}" loading="lazy" title="Video de la artesana" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div>`:`<div class="empty">Los videos se mostrarán aquí cuando la artesana añada su enlace de YouTube.<br><span class="muted small">También estarán disponibles los enlaces a sus demás redes sociales.</span></div>`}</div>${ratingPanel('artisan',a.name)}</div>`;break;}
case 'favoritos':body=`<div class="container">${title('Tu selección','Mis favoritos','Guarda productos para volver a verlos. No necesitas una cuenta.')} ${cards(all().filter(p=>state.favorites.includes(p.id)))}</div>`;break;
case 'panel':body=dash(`<span class="eyebrow">Tu espacio de trabajo</span><h1>¡Hola, ${esc(state.artisan.name.split(' ')[0])}!</h1><p class="muted">Desde aquí puedes publicar tus artesanías y compartirlas con nuevos clientes.</p><div class="grid2 main-actions"><a class="surface action-tile" href="nuevo.html"><span class="action-emoji">📷</span><h3>Agregar producto</h3><p>Sube tus fotos, prepara la descripción y aprueba todo en la misma página.</p><span class="smalllinks">Crear una artesanía →</span></a><a class="surface action-tile" href="difusion.html"><span class="action-emoji">📣</span><h3>Difundir en redes</h3><p>Obtén textos para Facebook, Instagram, TikTok y WhatsApp; apruébalos y compártelos.</p><span class="smalllinks">Preparar publicación →</span></a></div><div class="grid3" style="margin:25px 0"><div class="stat"><strong>${all().filter(p=>p.artisan===state.artisan.name).length}</strong>Mis productos</div><div class="stat"><strong>${state.posted.length}</strong>Productos agregados por mí</div><div class="stat"><strong>4</strong>Redes para compartir</div></div><div class="section"><div class="section-head"><h2>Mis productos</h2><a class="smalllinks" href="nuevo.html">+ Agregar otro</a></div>${cards(all().filter(p=>p.artisan===state.artisan.name))}<div class="row" style="margin-top:23px"><a class="btn alt" href="mi-perfil.html">Editar mi perfil</a><button class="btn ghost smallbtn" id="logout">Cerrar sesión</button><button class="btn warn smallbtn" id="resetDemo">Restablecer mis datos</button></div></div>`);break;
case 'nuevo':{let d=state.draft,a=d.ai;body=dash(`<span class="eyebrow">Crear una artesanía</span><h1>Agregar producto</h1><p class="muted">Todo en una sola página: completa los datos, prepara tus fotografías y descripción, revisa y publica.</p><div class="steps"><span class="step on">1. Cuenta tu historia</span><span class="step">2. Prepara y aprueba</span><span class="step">3. Publica y comparte</span></div><form class="panel" id="productForm"><h3>Datos del producto</h3><div class="field"><label for="prodName">¿Cómo se llama?</label><input class="input" id="prodName" placeholder="Ej. Bolso tejido a mano" required value="${attr(d.name)}"></div><div class="grid2"><div class="field"><label for="prodCategory">Categoría</label><select class="select" id="prodCategory">${['Bolsos','Textiles','Decoración','Accesorios','Otros'].map(x=>`<option ${d.category===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="prodMaterial">¿De qué material está hecho?</label><input class="input" id="prodMaterial" placeholder="Ej. Algodón" required value="${attr(d.material)}"></div></div><div class="grid2"><div class="field"><label for="prodPrice">Precio (S/)</label><input class="input" id="prodPrice" type="number" min="0" step="0.5" placeholder="Ej. 85" value="${attr(d.price)}"></div><div class="field"><label for="prodDim">Medidas</label><input class="input" id="prodDim" placeholder="Ej. 30 × 25 cm" value="${attr(d.dimensions)}"></div></div><h3>Fotografías</h3><p class="muted small">Puedes subir hasta 3: frente, lateral y detalle. O usar una imagen de ejemplo para recorrer el proceso.</p><div class="uploads">${[0,1,2].map(i=>imgLabel(d.photos[i],i)).join('')}</div><button type="button" class="btn ghost smallbtn" id="examplePhoto" style="margin-top:12px">Usar fotografía de ejemplo</button><div class="field" style="margin-top:20px"><label for="prodStory">La historia detrás del producto</label><textarea class="textarea" id="prodStory" placeholder="Cuéntanos cómo nació esta pieza...">${esc(d.story)}</textarea><small class="muted">También puedes utilizar el dictado del teclado de tu celular.</small></div><div class="field"><label for="prodCare">Cuidados del producto</label><input class="input" id="prodCare" placeholder="Ej. Lavar a mano y secar a la sombra" value="${attr(d.care)}"></div><div class="row"><button class="btn" type="submit">✓ Guardar datos y continuar aquí</button><span class="muted small">No perderás tus datos al volver a esta página.</span></div></form><section class="section" id="preparar"><span class="eyebrow">Tu asistente creativo</span><h2>Prepara y revisa tu publicación</h2><p class="muted">Utiliza estos botones cuando hayas completado el nombre y el material. Tú decides qué publicar.</p><div class="grid2"><div class="panel"><h3>📷 Fotografía <span class="tag ${a.imageOK?'':'demo'}" id="photoStatus">${a.imageOK?'✓ Aprobada':'Pendiente'}</span></h3><div class="preview" id="imagePreview">${a.image?`<img src="${src(a.image)}" alt="Foto preparada">`:d.photos[0]?`<img src="${src(d.photos[0])}" alt="Foto original">`:'Sube una foto o usa el ejemplo'}</div><p class="muted small">La vista aplica un encuadre uniforme sobre tu foto original.</p><div class="row"><button type="button" class="btn alt smallbtn" id="generateImage">✦ Preparar foto</button><button type="button" class="btn smallbtn" id="approveImage" ${!a.image?'disabled':''}>✓ Aprobar foto</button><button type="button" class="btn ghost smallbtn" id="retryImage" ${!d.photos[0]?'disabled':''}>↻ Otra versión</button></div></div><div class="panel"><h3>✍️ Descripción <span class="tag ${a.textOK?'':'demo'}" id="textStatus">${a.textOK?'✓ Aprobada':'Pendiente'}</span></h3><p class="muted small">Propuesta editable. Puedes cambiar cualquier palabra antes de aprobarla.</p><textarea id="approveTextArea" class="textarea" rows="9" placeholder="Aquí aparecerá la descripción...">${esc(a.text)}</textarea><div class="row" style="margin-top:13px"><button type="button" class="btn alt smallbtn" id="generateText">✦ Generar descripción</button><button type="button" class="btn smallbtn" id="approveText" ${!a.text?'disabled':''}>✓ Aprobar texto</button><button type="button" class="btn ghost smallbtn" id="retryText">↻ Otra versión</button></div></div></div><p class="muted small" style="margin-top:14px">Las propuestas de texto utilizan plantillas y el encuadre de foto es local; no se conecta a un servicio de IA.</p><div class="panel publish-panel" style="margin-top:20px"><h3>¿Todo está como lo deseas?</h3><p id="publishHint" class="muted">${a.imageOK&&a.textOK?'Fotografía y descripción aprobadas.':'Aprueba tanto la fotografía como la descripción para continuar.'}</p><button type="button" class="btn" id="publishProduct" ${!(a.imageOK&&a.textOK&&draftOK())?'disabled':''}>✓ Publicar producto en khipuFibra</button><p class="muted small">Después podrás preparar mensajes para tus redes sociales.</p></div></section>`);break;}
case 'estudio':case 'revision':location.replace('nuevo.html#preparar');return;
case 'difusion':{let own=all().filter(p=>p.artisan===state.artisan.name);let selected=new URLSearchParams(location.search).get('producto');let chosen=own.find(p=>String(p.id)===selected)||own[0];body=dash(`<span class="eyebrow">Solo para artesanas · Difusión digital</span><h1 style="font-size:40px">Comparte tus creaciones</h1><p class="muted">Elige una pieza, prepara tu mensaje y compártelo. Tú decides qué publicar.</p><div class="panel"><div class="grid2"><div class="field"><label for="shareProduct">1. ¿Qué producto quieres compartir?</label><select id="shareProduct" class="select">${own.map(p=>`<option value="${attr(p.id)}" ${chosen&&p.id===chosen.id?'selected':''}>${esc(p.name)}</option>`).join('')||'<option value="">Primero publica un producto</option>'}</select></div><div class="field"><label>2. ¿En qué red social?</label><select id="shareChannel" class="select" hidden aria-hidden="true"><option value="facebook">Facebook</option><option value="instagram">Instagram</option><option value="tiktok">TikTok</option><option value="whatsapp">WhatsApp</option></select></div></div><div class="social-network-choices" aria-label="Redes para compartir"><button type="button" class="social-net on" data-social="facebook">f Facebook</button><button type="button" class="social-net" data-social="instagram">◎ Instagram</button><button type="button" class="social-net" data-social="tiktok">♫ TikTok</button><button type="button" class="social-net" data-social="whatsapp">☏ WhatsApp</button></div><div id="socialProductCard" class="share-product-card"><img id="socialProductImage" src="${chosen?src(chosen.img):'assets/bolso.svg'}" alt="Imagen del producto"><div><b id="socialProductName">${chosen?esc(chosen.name):'Sin productos publicados'}</b><p class="muted small">Esta foto acompañará tu publicación cuando la aplicación lo permita.</p><a id="socialProductLink" class="smalllinks" href="${chosen?'producto.html?id='+encodeURIComponent(chosen.id):'catalogo.html'}" target="_blank" rel="noopener">Ver ficha pública ↗</a></div></div><div class="field"><label for="shareStyle">3. ¿Cómo quieres que suene el mensaje?</label><select id="shareStyle" class="select"><option value="emocional">Cercano y emotivo</option><option value="comercial">Para invitar a comprar</option><option value="creativo">Breve y creativo</option></select></div><div class="row" style="margin:4px 0 16px"><button id="generateSocial" type="button" class="btn" ${!chosen?'disabled':''}>✦ Generar descripción</button><button id="retrySocial" type="button" class="btn alt" ${!chosen?'disabled':''}>↻ Regenerar</button></div><p class="muted small">${cloud.enabled?'La descripción se generará mediante IA real cuando actives la función segura de Supabase. Cada resultado requiere tu aprobación.':'Los textos se preparan localmente hasta que conectes Supabase y la IA real.'}</p><div class="field"><label for="socialPreview">4. Revisa y edita el texto</label><textarea id="socialPreview" class="textarea" rows="7" placeholder="Pulsa «Crear descripción» para empezar..."></textarea></div><div class="row" style="margin-bottom:12px"><button id="approveSocial" type="button" class="btn" disabled>✓ Aprobar descripción</button><button id="copySocial" type="button" class="btn alt" disabled>⧉ Copiar texto y enlace</button></div><div id="shareStatus" class="notice" role="status">Prepara el mensaje y apruébalo antes de compartir.</div><div class="divider"></div><h3>5. Comparte tu producto</h3><p class="small muted">Para vincular tus redes, entra en <a href="mi-perfil.html" class="smalllinks">Mi perfil y redes →</a>. Guardar un enlace no autoriza la publicación automática.</p><p id="channelHelp" class="muted small">Facebook permite compartir el enlace, pero por privacidad no acepta insertar automáticamente tu texto en una publicación personal.</p><div class="row"><button id="shareNative" class="btn" type="button" disabled>↗ Compartir imagen, texto y enlace</button><button id="downloadPhoto" class="btn alt" type="button" ${!chosen?'disabled':''}>↓ Descargar imagen</button><button id="sharePlatform" class="btn ghost" type="button" disabled>f Abrir Facebook</button></div><p class="muted small" style="margin-top:15px">En celulares compatibles intentaremos compartir directamente la imagen, el texto y el enlace. Algunas redes no aceptan todos los elementos a la vez; en ese caso podrás descargar la foto y pegar el texto copiado. Las publicaciones requieren tu confirmación en cada red.</p></div><div class="section"><div class="surface"><h3>Difunde también tu perfil</h3><p>Comparte tu historia y reúne tus productos en un solo enlace.</p>${link('Ver mi perfil público →','artesana.html?nombre='+encodeURIComponent(state.artisan.name),'btn alt')}</div></div>`);break;}
case 'mi-perfil':{let a=state.artisan;body=dash(`<span class="eyebrow">Tu identidad digital</span><h1 style="font-size:40px">Mi perfil</h1><p class="muted">Cuenta tu historia y coloca tus redes. Los visitantes podrán conocerte y seguir tu trabajo.</p><form class="panel" id="profileForm"><div class="grid2"><div class="field"><label>Nombre público</label><input class="input" id="profileName" value="${attr(a.name)}" required></div><div class="field"><label>Ciudad / comunidad</label><input class="input" id="profileCity" value="${attr(a.city)}"></div></div><div class="field"><label>Foto de perfil (opcional)</label><input class="input" id="profileAvatar" type="file" accept="image/png,image/jpeg,image/webp"><small>Una foto de la artesana o de su taller ayuda a dar confianza.</small></div><div class="field"><label>¿Qué artesanías elaboras?</label><input class="input" id="profileSpecialty" value="${attr(a.specialty)}"></div><div class="field"><label>Tu historia</label><textarea class="textarea" id="profileBio">${esc(a.bio)}</textarea></div><div class="field"><label>¿Qué significa para ti tu trabajo?</label><textarea class="textarea" id="profileStory">${esc(a.story)}</textarea></div><h3>Mis redes sociales</h3><p class="muted small">Añade solamente las redes que utilices. Los enlaces aparecerán en tu perfil público. Vincular cuentas para publicar automáticamente requerirá autorización adicional de Meta.</p>${[['Facebook','facebook'],['Instagram','instagram'],['YouTube','youtube'],['TikTok','tiktok']].map(([n,k])=>`<div class="field"><label>${n}</label><input class="input" type="url" id="${k}" placeholder="https://..." value="${attr(a[k])}"></div>`).join('')}<div class="field"><label>WhatsApp para consultas (9 dígitos)</label><input class="input" id="profileWhatsapp" inputmode="tel" placeholder="Ej. 933860919" value="${attr(a.whatsapp||'')}"></div><div class="field"><label>Años de experiencia / trayectoria</label><input class="input" id="profileExperience" value="${attr(a.experience||'')}"></div><div class="field"><label>Ferias y reconocimientos</label><textarea class="textarea" id="profileFair">${esc(a.fair||'')}</textarea></div><div class="field"><label>Un video de YouTube para destacar</label><input class="input" id="profileVideo" type="url" placeholder="https://www.youtube.com/watch?v=..." value="${attr(a.video)}"><small>Se mostrará directamente en tu perfil público.</small></div><div class="row"><button type="submit" class="btn">✓ Guardar mi perfil</button>${link('Ver cómo se ve →','artesana.html?nombre='+encodeURIComponent(a.name),'btn alt')}</div></form><section class="panel admin-section" id="accountSecurity"></section><div class="logo-tip" style="margin-top:20px"><b>Espacio del logotipo khipuFibra</b><p class="muted small">Coloca tu imagen PNG en assets/logo.png y el encabezado la mostrará automáticamente en todas las páginas.</p></div>`);break;}
default:body='<div class="container section"><h1>Página no encontrada</h1></div>'}
document.querySelector('#app').innerHTML=top()+`<main class="main" id="mainContent" tabindex="-1">${body}</main>`+foot();hook();setupMenu();if(typeof CustomEvent==='function')window.dispatchEvent(new CustomEvent('khipu:rendered'));}
function youtubeEmbed(url){try{let u=new URL(url);if(!['youtube.com','www.youtube.com','m.youtube.com','youtu.be'].includes(u.hostname))return null;let id=u.hostname==='youtu.be'?u.pathname.split('/')[1]:u.searchParams.get('v')||(u.pathname.match(/\/shorts\/([\w-]+)/)||[])[1];return /^[\w-]{11}$/.test(id||'')?'https://www.youtube-nocookie.com/embed/'+id:null}catch{return null}}
function getDraft(){let d=state.draft;d.name=document.getElementById('prodName').value.trim();d.category=document.getElementById('prodCategory').value;d.material=document.getElementById('prodMaterial').value.trim();d.price=document.getElementById('prodPrice').value;d.dimensions=document.getElementById('prodDim').value;d.story=document.getElementById('prodStory').value;d.care=document.getElementById('prodCare').value;store();}
function generateText(){let d=state.draft,a=d.ai;const variants=[`Conoce ${d.name}, una pieza artesanal elaborada con ${d.material}. ${d.story||'Cada detalle refleja dedicación y trabajo manual.'} ${d.dimensions?'Sus medidas son '+d.dimensions+'.':''} Consulta disponibilidad y opciones de personalización directamente con la artesana.`,`El valor del trabajo hecho a mano se refleja en ${d.name}. Elaborado con ${d.material}, ${d.story||'este producto forma parte de una tradición de creación artesanal.'} Descubre más sobre esta pieza y contacta a su creadora.`,`Una creación con identidad: ${d.name}. Material principal: ${d.material}. ${d.story||'Elaborado cuidadosamente de forma artesanal.'} ${d.care?'Cuidados: '+d.care+'.':''} Pregunta por disponibilidad y detalles.`];a.tv=(a.tv||0)+1;a.text=variants[(a.tv-1)%variants.length];a.textOK=false;store()}
function generateImage(){let d=state.draft,a=d.ai;if(!d.photos[0])return;const i=new Image();i.onload=()=>{const canvas=document.createElement('canvas');canvas.width=960;canvas.height=780;const ctx=canvas.getContext('2d');ctx.fillStyle=['#f3e9db','#e5e9e0','#eee7e0'][(a.iv||0)%3];ctx.fillRect(0,0,960,780);ctx.fillStyle='#fffdf9';ctx.fillRect(75,65,810,650);let w=780,h=600,s=Math.min(w/i.width,h/i.height);let x=(960-i.width*s)/2,y=(780-i.height*s)/2;ctx.drawImage(i,x,y,i.width*s,i.height*s);a.image=canvas.toDataURL('image/jpeg',.82);a.iv=(a.iv||0)+1;a.imageOK=false;store();show();document.getElementById('preparar')?.scrollIntoView({block:'start'});toast('Fotografía preparada. Revisa el resultado antes de aprobar.')};i.src=d.photos[0]}
function socialText(p,ch,style='emocional',version=0){const n=p.name||'Esta artesanía',m=p.material||'materiales cuidadosamente elegidos',story=(p.story||'').trim(),detail=story?story.replace(/\s+/g,' ').slice(0,160):'',name=state.artisan.name;const hashtag='#khipuFibra #ArtesaniaPeruana #HechoAMano';const intro={emocional:[`Cada pieza tiene una historia. Hoy te presentamos ${n}.`,`Detrás de cada creación hay dedicación: conoce ${n}.`,`Hay detalles que solo el trabajo hecho a mano puede contar. Descubre ${n}.`,`Una creación artesanal que merece ser conocida: ${n}.`,`Las manos artesanas transforman materiales en historias. Esta es ${n}.`],comercial:[`¿Buscas un detalle especial? Conoce ${n}.`,`Descubre ${n}, una propuesta artesanal para regalar o disfrutar.`,`Haz espacio para lo hecho a mano: te presentamos ${n}.`,`Te invitamos a conocer ${n} y sus detalles.`,`Una pieza con identidad: descubre ${n}.`],creativo:[`Texturas, manos e historias: ${n}.`,`Lo artesanal tiene algo diferente. Mira ${n}.`,`De nuestro taller para ti: ${n}.`,`¿Ya conocías ${n}?`,`Un detalle, muchas historias: ${n}.`]};const v=((version%5)+5)%5;const first=intro[style]?.[v]||intro.emocional[v];const material=`Elaborado con ${m}.`;const history=detail&&!detail.toLowerCase().includes('consulta disponibilidad')?` ${detail}`:'';if(ch==='whatsapp')return `${first}\n${material}${history}\nConoce más y consulta directamente con la artesana.`;if(ch==='tiktok')return `${first}\n🎥 Idea para video: muestra el producto, acerca la cámara a sus detalles y presenta a la artesana.\n${hashtag} #Artesanas`;if(ch==='instagram')return `${first}\n\n${material}${history}\n\nConoce su historia en khipuFibra.\n${hashtag} #Artesania`;return `${first}\n\n${material}${history}\n\nDescubre el producto y contacta a ${name} a través de khipuFibra.\n\n${hashtag}`}
function renderCatalog(){const normalize=text=>String(text).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const q=normalize(document.getElementById('search')?.value||'').trim(),cat=document.querySelector('#filters button.on')?.dataset.cat||'Todos',sort=document.getElementById('sort')?.value||'default';const ps=all().filter(p=>(cat==='Todos'||p.category===cat)&&normalize(p.name+' '+p.material+' '+p.artisan).includes(q));if(sort!=='default')ps.sort((a,b)=>{const value=p=>p.price!==''&&p.price!=null&&Number.isFinite(Number(p.price))?Number(p.price):null;const av=value(a),bv=value(b);return av===null?bv===null?0:1:bv===null?-1:sort==='low'?av-bv:bv-av;});document.getElementById('catalogStatus').textContent=ps.length+' artesanía'+(ps.length===1?' encontrada':'s encontradas');document.getElementById('catalogResults').innerHTML=ps.length?cards(ps):'<div class="empty"><h2>No encontramos piezas con esa búsqueda</h2><p>Prueba otro nombre, material o categoría.</p><button type="button" class="btn alt" id="clearFilters">Limpiar búsqueda y filtros</button></div>';const clear=document.getElementById('clearFilters');if(clear)clear.onclick=()=>{document.getElementById('search').value='';document.getElementById('sort').value='default';document.querySelectorAll('#filters button').forEach((b,i)=>{b.classList.toggle('on',i===0);b.setAttribute('aria-pressed',String(i===0));});renderCatalog();document.getElementById('search').focus();};}
async function resize(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>{let i=new Image();i.onload=()=>{let s=Math.min(1,1100/Math.max(i.width,i.height));let c=document.createElement('canvas');c.width=Math.round(i.width*s);c.height=Math.round(i.height*s);c.getContext('2d').drawImage(i,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.74))};i.onerror=reject;i.src=r.result};r.onerror=reject;r.readAsDataURL(file)})}
async function copy(t){try{await navigator.clipboard.writeText(t);toast('Texto copiado. Ya puedes pegarlo en tu red social.')}catch{let ta=document.createElement('textarea');ta.value=t;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();toast('Texto copiado.')}}
const newTab=url=>window.open(url,'_blank','noopener,noreferrer');
function setupMenu(){const toggle=document.getElementById('toggleMenu'),nav=document.getElementById('mainnav');const close=()=>{nav.classList.remove('open');document.body.classList.remove('menu-open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Abrir menú');toggle.textContent='Menú';document.getElementById('mainContent').inert=false;document.querySelector('.footer').inert=false;};toggle.onclick=()=>{const open=!nav.classList.contains('open');if(!open)return close();nav.classList.add('open');document.body.classList.add('menu-open');toggle.setAttribute('aria-expanded','true');toggle.setAttribute('aria-label','Cerrar menú');toggle.textContent='Cerrar';document.getElementById('mainContent').inert=true;document.querySelector('.footer').inert=true;};window.onresize=()=>{if(window.innerWidth>=1024)close();};nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',close));document.onkeydown=e=>{if(!nav.classList.contains('open'))return;if(e.key==='Escape'){close();toggle.focus();}if(e.key==='Tab'){const links=[...nav.querySelectorAll('a')],last=links[links.length-1];if(!e.shiftKey&&document.activeElement===last){e.preventDefault();toggle.focus();}else if(e.shiftKey&&document.activeElement===toggle){e.preventDefault();last.focus();}}};}
function hook(){document.querySelectorAll('[data-product-photo]').forEach(button=>button.onclick=()=>{document.getElementById('productImage').src=button.dataset.productPhoto;document.querySelectorAll('[data-product-photo]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));});document.querySelectorAll('.rating-form').forEach(form=>{form.onsubmit=e=>{e.preventDefault();let data=new FormData(form),name=String(data.get('name')||'').trim(),comment=String(data.get('comment')||'').trim(),score=Number(data.get('score'));if(name.length<2||comment.length<10||score<1||score>5)return toast('Completa tu nombre, calificación y un comentario.');const kind=form.dataset.kind,target=form.dataset.target;if(cloud.enabled){cloud.sendReview({kind,target,name,comment,score}).then(()=>{form.reset();toast('¡Gracias! Tu valoración fue enviada para revisión.');}).catch(err=>toast('No se pudo enviar: '+err.message));return}state.ratings.push({kind,target,name,comment,score,date:new Date().toLocaleDateString('es-PE')});if(store()){show();toast('¡Gracias! Tu valoración ha sido publicada.')}}});if(!document.body.dataset.favHook) {document.body.dataset.favHook='1';document.body.addEventListener('click',e=>{const b=e.target.closest('[data-fav]');if(!b)return;let id=b.dataset.fav;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];store();if(page==='favoritos')show();else document.querySelectorAll('[data-fav]').forEach(button=>{const saved=state.favorites.includes(button.dataset.fav);button.classList.toggle('selected',saved);button.setAttribute('aria-pressed',String(saved));button.textContent=button.hasAttribute('data-favorite-label')?(saved?'♥ Guardado en favoritos':'♡ Guardar en favoritos'):(saved?'♥':'♡');if(!button.hasAttribute('data-favorite-label')){const p=get(button.dataset.fav);button.setAttribute('aria-label',(saved?'Quitar de':'Guardar en')+' favoritos: '+(p?.name||'producto'));}});toast('Favoritos actualizados.');});}
if(page==='catalogo'){let cats=['Todos','Bolsos','Textiles','Decoración','Accesorios','Otros'];document.getElementById('filters').innerHTML=cats.map((cat,i)=>`<button data-cat="${cat}" aria-pressed="${i===0}" class="${i===0?'on':''}">${cat}</button>`).join('');document.getElementById('filters').onclick=e=>{let b=e.target.closest('button');if(!b)return;document.querySelectorAll('#filters button').forEach(x=>{x.classList.toggle('on',x===b);x.setAttribute('aria-pressed',String(x===b));});renderCatalog()};document.getElementById('search').oninput=renderCatalog;document.getElementById('sort').onchange=renderCatalog;renderCatalog()}
if(page==='panel'){document.getElementById('logout').onclick=async()=>{try{await cloud.logout();state={...structuredClone(initial),favorites:state.favorites};store();location.replace('index.html');}catch{toast('No se pudo cerrar la sesión. Revisa tu conexión y vuelve a intentarlo.');}};document.getElementById('resetDemo').onclick=()=>{if(cloud.enabled)return toast('Los datos reales no se borran desde este botón.');if(confirm('¿Borrar todos los datos de demostración de este navegador?')){localStorage.removeItem(KEY);location.href='index.html'}}}
if(page==='nuevo'){
const updateDraft=()=>{getDraft();const a=state.draft.ai;a.textOK=false;a.imageOK=false;store()};
const form=document.getElementById('productForm');
form.querySelectorAll('input:not([type=file]),select,textarea').forEach(el=>el.addEventListener('change',updateDraft));
form.onsubmit=e=>{e.preventDefault();updateDraft();if(!draftOK())return toast('Completa nombre y material.');document.getElementById('preparar').scrollIntoView({behavior:'smooth'});toast('Datos guardados. Prepara y revisa tu contenido aquí.')};
document.querySelectorAll('[data-photo]').forEach(input=>input.onchange=async()=>{if(!input.files?.[0])return;try{let i=+input.dataset.photo;state.draft.photos[i]=await resize(input.files[0]);state.draft.ai.image='';state.draft.ai.imageOK=false;store();input.parentElement.querySelector('img')?.remove();let img=document.createElement('img');img.src=state.draft.photos[i];input.parentElement.insertBefore(img,input);toast('Fotografía guardada.')}catch{toast('No se pudo leer esta imagen.')}});
document.getElementById('examplePhoto').onclick=()=>{state.draft.photos[0]='assets/bolso.svg';state.draft.ai.image='';state.draft.ai.imageOK=false;store();show();toast('Fotografía de ejemplo seleccionada.');};
document.getElementById('generateText').onclick=async()=>{getDraft();if(!draftOK())return toast('Completa primero el nombre y el material.');if(cloud.enabled){try{const d=state.draft;const txt=await cloud.generateDescription({kind:'producto',product:{name:d.name,material:d.material,story:d.story,dimensions:d.dimensions,care:d.care},previous:d.ai.text});d.ai.text=txt;d.ai.textOK=false;store()}catch(e){return toast('IA: '+e.message)}}else generateText();document.getElementById('approveTextArea').value=state.draft.ai.text;document.getElementById('textStatus').textContent='Pendiente';document.getElementById('approveText').disabled=false;document.getElementById('publishProduct').disabled=true;toast('Descripción preparada. Puedes editarla antes de aprobar.')};
document.getElementById('retryText').onclick=()=>document.getElementById('generateText').click();
document.getElementById('generateImage').onclick=()=>{getDraft();if(!state.draft.photos[0])return toast('Sube una foto o pulsa «Usar fotografía de ejemplo».');generateImage()};
document.getElementById('retryImage').onclick=()=>document.getElementById('generateImage').click();
document.getElementById('approveTextArea').oninput=e=>{state.draft.ai.text=e.target.value;state.draft.ai.textOK=false;store();document.getElementById('textStatus').textContent='Pendiente';document.getElementById('publishProduct').disabled=true;document.getElementById('approveText').disabled=!e.target.value.trim()};
const refreshStatus=()=>{let a=state.draft.ai;document.getElementById('photoStatus').textContent=a.imageOK?'✓ Aprobada':'Pendiente';document.getElementById('textStatus').textContent=a.textOK?'✓ Aprobada':'Pendiente';document.getElementById('publishProduct').disabled=!(a.imageOK&&a.textOK&&draftOK());document.getElementById('publishHint').textContent=a.imageOK&&a.textOK?'Fotografía y descripción aprobadas.':'Aprueba tanto la fotografía como la descripción para continuar.'};
document.getElementById('approveImage').onclick=()=>{if(!state.draft.ai.image)return toast('Primero prepara la fotografía.');state.draft.ai.imageOK=true;store();refreshStatus();toast('Fotografía aprobada.')};
document.getElementById('approveText').onclick=()=>{let v=document.getElementById('approveTextArea').value.trim();if(!v)return toast('Primero prepara la descripción.');state.draft.ai.text=v;state.draft.ai.textOK=true;store();refreshStatus();toast('Descripción aprobada.')};
document.getElementById('publishProduct').onclick=async()=>{getDraft();let a=state.draft.ai,d=state.draft;if(!a.imageOK||!a.textOK||!draftOK())return toast('Aprueba la fotografía y la descripción.');let p={id:'p'+Date.now(),name:d.name,category:d.category,material:d.material,price:d.price||'Consultar',dimensions:d.dimensions,care:d.care,story:a.text,img:a.image,artisan:state.artisan.name,stock:d.stock||'Consultar',time:'Consultar',collection:'Mis creaciones'};if(cloud.enabled){try{const id=await cloud.saveProduct(p);state.draft=JSON.parse(JSON.stringify(initial.draft));store();location.href='difusion.html?producto='+encodeURIComponent(id)}catch(e){toast('No se publicó: '+e.message)}return}state.products.unshift(p);state.posted.unshift({id:p.id,date:new Date().toISOString()});state.draft=JSON.parse(JSON.stringify(initial.draft));store();location.href='difusion.html?producto='+encodeURIComponent(p.id)};
}

if(page==='difusion'){
 const productSelect=document.getElementById('shareProduct'),channelSelect=document.getElementById('shareChannel'),styleSelect=document.getElementById('shareStyle'),preview=document.getElementById('socialPreview'),status=document.getElementById('shareStatus');
 const approve=document.getElementById('approveSocial'),copyButton=document.getElementById('copySocial'),shareNative=document.getElementById('shareNative'),sharePlatform=document.getElementById('sharePlatform'),downloadPhoto=document.getElementById('downloadPhoto');
 let version=0,isApproved=false;
 const product=()=>all().find(p=>String(p.id)===productSelect.value&&p.artisan===state.artisan.name);
 const productUrl=()=>new URL('producto.html?id='+encodeURIComponent(product()?.id||''),location.href).href;
 const approvedMessage=()=>preview.value.trim()+'\n\n'+productUrl();
 const setApproved=(ok)=>{isApproved=ok;approve.disabled=!preview.value.trim()||ok;copyButton.disabled=!ok;shareNative.disabled=!ok;sharePlatform.disabled=!ok;status.className=ok?'success':'notice';status.textContent=ok?'✓ Descripción aprobada. Ya puedes compartirla.':'Revisa el texto y pulsa «Aprobar descripción».'};
 const syncChannel=()=>{const c=channelSelect.value;sharePlatform.textContent=({facebook:'f Abrir Facebook',instagram:'◎ Abrir Instagram',tiktok:'♫ Abrir TikTok',whatsapp:'☏ Abrir WhatsApp'})[c];document.getElementById('channelHelp').textContent=({facebook:'Facebook comparte la vista previa del enlace, pero no permite insertar automáticamente la descripción en una publicación personal. Copia y pega el texto si lo necesitas.',instagram:'Instagram suele requerir subir la imagen desde su propia aplicación. Puedes descargarla y pegar la descripción.',tiktok:'Para TikTok prepara una fotografía o video y su descripción. El enlace puede ir en tu perfil según las funciones disponibles.',whatsapp:'WhatsApp puede compartir directamente el texto y enlace. En celulares compatibles también intentaremos enviar la fotografía.'})[c]};
 const syncProduct=()=>{let p=product();document.getElementById('socialProductImage').src=p?src(p.img):'assets/bolso.svg';document.getElementById('socialProductName').textContent=p?p.name:'Sin productos publicados';document.getElementById('socialProductLink').href=p?'producto.html?id='+encodeURIComponent(p.id):'catalogo.html';downloadPhoto.disabled=!p;preview.value='';setApproved(false);syncChannel()};
 const regenerate=async()=>{let p=product();if(!p)return toast('Primero publica un producto.');if(cloud.enabled){try{const text=await cloud.generateDescription({kind:'social',network:channelSelect.value,style:styleSelect.value,product:p,previous:preview.value});preview.value=text;version++}catch(e){toast('IA: '+e.message);return}}else preview.value=socialText(p,channelSelect.value,styleSelect.value,version++);setApproved(false)};
 document.getElementById('generateSocial').onclick=regenerate;document.getElementById('retrySocial').onclick=regenerate;
 document.querySelectorAll('[data-social]').forEach(b=>b.onclick=()=>{channelSelect.value=b.dataset.social;channelSelect.dispatchEvent(new Event('change'))});const markSocial=()=>document.querySelectorAll('[data-social]').forEach(b=>b.classList.toggle('on',b.dataset.social===channelSelect.value));productSelect.onchange=()=>{version=0;syncProduct()};channelSelect.onchange=()=>{version=0;preview.value='';setApproved(false);syncChannel();markSocial()};markSocial();styleSelect.onchange=()=>{version=0;preview.value='';setApproved(false)};
 preview.oninput=()=>setApproved(false);
 approve.onclick=()=>{if(preview.value.trim())setApproved(true)};
 copyButton.onclick=()=>{if(isApproved)copy(approvedMessage())};
 async function imageFile(){let p=product();if(!p)return null;let response=await fetch(src(p.img));if(!response.ok)throw new Error('No se pudo leer la imagen');let blob=await response.blob();let mime=blob.type||'image/png';if(mime==='image/svg+xml'){let img=new Image();let url=URL.createObjectURL(blob);try{await new Promise((yes,no)=>{img.onload=yes;img.onerror=no;img.src=url});let canvas=document.createElement('canvas');canvas.width=1200;canvas.height=1200;let ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,1200,1200);let r=Math.min(1100/img.width,1100/img.height);ctx.drawImage(img,(1200-img.width*r)/2,(1200-img.height*r)/2,img.width*r,img.height*r);blob=await new Promise(yes=>canvas.toBlob(yes,'image/png'))}finally{URL.revokeObjectURL(url)}mime='image/png'}let ext=mime.includes('jpeg')?'jpg':mime.includes('webp')?'webp':'png';let filename=(p.name||'artesania').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'-').slice(0,45)+'.'+ext;return new File([blob],filename,{type:mime})}
 downloadPhoto.onclick=async()=>{try{let f=await imageFile();if(!f)return;let u=URL.createObjectURL(f);let a=document.createElement('a');a.href=u;a.download=f.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000);toast('Imagen descargada. Puedes subirla a tu red social.')}catch{toast('No se pudo descargar la imagen. Intenta abrir la ficha del producto.')}};
 shareNative.onclick=async()=>{if(!isApproved||!product())return;let data={title:product().name,text:preview.value.trim(),url:productUrl()};try{let f=await imageFile();if(f&&navigator.canShare?.({files:[f]})&&navigator.share){await navigator.share({files:[f],text:approvedMessage(),title:product().name});return}}catch(e){if(e.name==='AbortError')return}
 if(navigator.share){try{await navigator.share(data);return}catch(e){if(e.name==='AbortError')return}}await copy(approvedMessage());toast('Se copiaron texto y enlace. Usa «Descargar imagen» para agregar la fotografía.');};
 sharePlatform.onclick=async()=>{if(!isApproved)return;let c=channelSelect.value;if(c==='whatsapp')return newTab('https://wa.me/?text='+encodeURIComponent(approvedMessage()));if(c==='facebook'){await copy(approvedMessage());newTab('https://www.facebook.com/sharer/sharer.php?u='+encodeURIComponent(productUrl()));return toast('Texto y enlace copiados. Facebook no pega el texto automáticamente; pégalo tú en la publicación.')}await copy(approvedMessage());newTab(c==='instagram'?'https://www.instagram.com/':'https://www.tiktok.com/');toast('Texto y enlace copiados. Descarga la foto y súbela desde la aplicación.');};
 syncProduct();
}
if(page==='mi-perfil'){window.khipuSecurity?.mount(document.getElementById('accountSecurity'));document.getElementById('profileForm').onsubmit=async e=>{e.preventDefault();let a=state.artisan;let old=a.name;a.name=document.getElementById('profileName').value.trim()||old;a.city=document.getElementById('profileCity').value;a.specialty=document.getElementById('profileSpecialty').value;a.bio=document.getElementById('profileBio').value;a.story=document.getElementById('profileStory').value;['facebook','instagram','youtube','tiktok'].forEach(k=>a[k]=document.getElementById(k).value.trim());a.video=document.getElementById('profileVideo').value.trim();a.whatsapp=document.getElementById('profileWhatsapp').value.replace(/[^0-9+]/g,'');a.experience=document.getElementById('profileExperience').value;a.fair=document.getElementById('profileFair').value;if(cloud.enabled){try{const f=document.getElementById('profileAvatar')?.files?.[0];if(f)a.avatar=await cloud.uploadAvatar(f);await cloud.saveProfile(a)}catch(err){toast('No se guardó: '+err.message);return}}state.products.forEach(p=>{if(p.artisan===old)p.artisan=a.name});store();toast('Perfil actualizado.');location.href='artesana.html?nombre='+encodeURIComponent(a.name)}}
if(page==='artesana'){document.getElementById('copyProfile').onclick=()=>copy(location.href);document.getElementById('showQr').onclick=()=>{const el=document.getElementById('qrPlace');if(el.innerHTML){el.innerHTML='';return}el.innerHTML='<p class="muted small">QR de demostración: requiere conexión a Internet y una URL pública para funcionar en otros celulares.</p><img alt="Código QR generado mediante servicio externo" style="max-width:190px" src="https://api.qrserver.com/v1/create-qr-code/?size=190x190&data='+encodeURIComponent(location.href)+'">'} }
}
async function boot(){
  if(!cloud.enabled)state.logged=false;
 if(cloud.enabled){
  try{
    const auth=await cloud.init();renderedUserId=auth.user?.id||null;
    const favorites=state.favorites;
    state={...structuredClone(initial),favorites,logged:!!auth.approved};
    // Keep only public preferences in shared localStorage. Drafts stay in this tab.
    localStorage.setItem(KEY,JSON.stringify({favorites}));
    localStorage.removeItem('quipufibra_mockup_v1');
    if(auth.approved){try{const saved=JSON.parse(sessionStorage.getItem('khipuFibra_private_'+auth.user.id)||'null');if(saved?.draft)state.draft={...initial.draft,...saved.draft,ai:{...initial.draft.ai,...saved.draft.ai}};}catch{cloud.clearPrivate();}}
   if(auth.approved){const p=await cloud.myProfile();state.artisan=p?{...initial.artisan,...p}:{...initial.artisan,name:auth.user?.user_metadata?.full_name||'Nueva artesana',facebook:'',instagram:'',tiktok:'',youtube:'',video:'',bio:'',story:'',whatsapp:'',city:'',specialty:'',experience:'',fair:''};}
   else state.artisan={...initial.artisan};
   const data=await cloud.list();cloudProfiles=data.profiles;cloudReviews=data.reviews;
   state.products=data.products; // solo los productos de Supabase, jamás los locales de otras sesiones
   if(auth.user&&!auth.approved)cloud.clearPrivate();
  }catch(e){console.error(e);state.logged=false;document.querySelector('#app').innerHTML='<main class="container section"><h2>No se pudo conectar con Supabase</h2><p>'+esc(e.message)+'</p><a href="index.html">Volver a inicio</a></main>';return;}
 }
 show();
}
const privatePages=['panel','nuevo','estudio','revision','difusion','mi-perfil'];
let booting=false,renderedUserId=null;
window.addEventListener('khipu:auth-change',event=>{
 if(event.detail.event==='INITIAL_SESSION')return;
 if(event.detail.event==='SIGNED_OUT'||(renderedUserId&&event.detail.userId&&renderedUserId!==event.detail.userId)){
  cloud.clearPrivate();state={...structuredClone(initial),favorites:state.favorites};
  if(privatePages.includes(page)){document.getElementById('app').replaceChildren();location.replace('acceso.html');}
 }
});
async function checkAccess(){if(!cloud.enabled||!privatePages.includes(page)||booting)return;booting=true;try{const auth=await cloud.init();if(!auth.approved||auth.user?.id!==renderedUserId){document.getElementById('app').replaceChildren();cloud.clearPrivate();location.replace('acceso.html');}}catch{document.getElementById('app').replaceChildren();location.replace('acceso.html');}finally{booting=false;}}
window.addEventListener('focus',checkAccess);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkAccess();});
boot();
})();
